"use client";

import Link from "next/link";
import { type FormEvent, useEffect, useState } from "react";

type AdminSession = {
  id: string;
  email: string;
  name: string;
};

type HospitalItem = {
  id: number;
  name: string;
  city: string;
  state: string;
  doctorCount: number;
};

function splitValues(value: string) {
  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

export default function HomePage() {
  const [sessionLoading, setSessionLoading] = useState(true);
  const [admin, setAdmin] = useState<AdminSession | null>(null);
  const [hospitals, setHospitals] = useState<HospitalItem[]>([]);
  const [message, setMessage] = useState("");
  const [hospitalForm, setHospitalForm] = useState({
    name: "",
    city: "",
    state: "",
    address: "",
    pincode: "",
    phone: "",
    email: "",
    website: "",
    rating: "4.5",
    specialties: "",
    isOpen24Hours: true,
  });
  const [doctorForm, setDoctorForm] = useState({
    hospitalId: "",
    name: "",
    specialty: "",
    experience: "",
    rating: "5",
    reviews: "0",
    qualification: "",
    college: "",
    tags: "",
    available: "Available Today",
    conditions: "",
  });

  async function loadSessionAndHospitals() {
    const sessionResponse = await fetch("/api/session", { cache: "no-store" });
    const sessionPayload = await sessionResponse.json();

    setAdmin(sessionPayload.admin || null);

    if (sessionPayload.admin) {
      const hospitalsResponse = await fetch("/api/hospitals", { cache: "no-store" });
      const hospitalsPayload = await hospitalsResponse.json();
      setHospitals(hospitalsPayload.hospitals || []);
    } else {
      setHospitals([]);
    }

    setSessionLoading(false);
  }

  useEffect(() => {
    let ignore = false;

    async function initialize() {
      const sessionResponse = await fetch("/api/session", { cache: "no-store" });
      const sessionPayload = await sessionResponse.json();

      if (ignore) {
        return;
      }

      setAdmin(sessionPayload.admin || null);

      if (sessionPayload.admin) {
        const hospitalsResponse = await fetch("/api/hospitals", { cache: "no-store" });
        const hospitalsPayload = await hospitalsResponse.json();

        if (ignore) {
          return;
        }

        setHospitals(hospitalsPayload.hospitals || []);
      } else {
        setHospitals([]);
      }

      setSessionLoading(false);
    }

    void initialize();

    return () => {
      ignore = true;
    };
  }, []);

  async function handleHospitalSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setMessage("");

    const response = await fetch("/api/hospitals", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...hospitalForm,
        rating: Number(hospitalForm.rating),
        specialties: splitValues(hospitalForm.specialties),
      }),
    });

    const payload = await response.json();

    if (!response.ok) {
      setMessage(payload.error || "Failed to create hospital.");
      return;
    }

    setMessage(`Hospital "${payload.hospital.name}" created successfully.`);
    setHospitalForm({
      name: "",
      city: "",
      state: "",
      address: "",
      pincode: "",
      phone: "",
      email: "",
      website: "",
      rating: "4.5",
      specialties: "",
      isOpen24Hours: true,
    });
    await loadSessionAndHospitals();
  }

  async function handleDoctorSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setMessage("");

    const response = await fetch("/api/doctors", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...doctorForm,
        hospitalId: Number(doctorForm.hospitalId),
        rating: Number(doctorForm.rating),
        reviews: Number(doctorForm.reviews),
        tags: splitValues(doctorForm.tags),
        conditions: splitValues(doctorForm.conditions),
      }),
    });

    const payload = await response.json();

    if (!response.ok) {
      setMessage(payload.error || "Failed to create doctor.");
      return;
    }

    setMessage(`Doctor "${payload.doctor.name}" added successfully.`);
    setDoctorForm({
      hospitalId: "",
      name: "",
      specialty: "",
      experience: "",
      rating: "5",
      reviews: "0",
      qualification: "",
      college: "",
      tags: "",
      available: "Available Today",
      conditions: "",
    });
    await loadSessionAndHospitals();
  }

  async function handleLogout() {
    await fetch("/api/logout", { method: "POST" });
    await loadSessionAndHospitals();
    setMessage("");
  }

  if (sessionLoading) {
    return <div className="flex min-h-screen items-center justify-center bg-slate-100 text-slate-600">Loading admin dashboard...</div>;
  }

  if (!admin) {
    return (
      <main className="min-h-screen bg-[linear-gradient(135deg,#e2e8f0_0%,#f8fafc_45%,#dbeafe_100%)] px-6 py-10 text-slate-900">
        <div className="mx-auto flex max-w-6xl flex-col gap-10 rounded-[32px] border border-white/70 bg-white/75 p-8 shadow-[0_30px_80px_rgba(15,23,42,0.12)] backdrop-blur md:p-12">
          <div className="grid gap-8 md:grid-cols-[1.2fr,0.8fr] md:items-center">
            <div>
              <p className="text-sm font-semibold uppercase tracking-[0.35em] text-blue-600">Hospital Admin</p>
              <h1 className="mt-4 max-w-3xl text-4xl font-semibold tracking-tight text-slate-950 md:text-6xl">Create hospitals and doctors from one admin panel.</h1>
              <p className="mt-5 max-w-2xl text-base leading-7 text-slate-600 md:text-lg">This admin app now writes hospital and doctor records directly to your shared Neon database, so you do not need to depend on seeded hospital data in `my-app`.</p>
              <div className="mt-8 flex flex-wrap gap-4">
                <Link href="/auth/register" className="rounded-full bg-slate-900 px-6 py-3 text-sm font-semibold text-white transition hover:bg-slate-800">Create Admin Account</Link>
                <Link href="/auth/login" className="rounded-full border border-slate-300 px-6 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Log In</Link>
              </div>
            </div>

            <div className="rounded-[28px] bg-slate-950 p-7 text-white shadow-[0_25px_60px_rgba(15,23,42,0.35)]">
              <p className="text-sm font-semibold uppercase tracking-[0.3em] text-cyan-300">What You Can Do</p>
              <div className="mt-6 space-y-4 text-sm leading-6 text-slate-200">
                <p>Register a hospital admin account with email and password.</p>
                <p>Add hospitals directly from this dashboard instead of `seed.js`.</p>
                <p>Add doctors for any hospital you create and keep `my-app` data live.</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-100 px-4 py-6 md:px-8">
      <div className="mx-auto max-w-7xl space-y-6">
        <section className="rounded-[28px] bg-slate-950 px-6 py-7 text-white shadow-[0_24px_60px_rgba(15,23,42,0.28)] md:px-8">
          <div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between">
            <div>
              <p className="text-sm font-semibold uppercase tracking-[0.3em] text-cyan-300">Signed In</p>
              <h1 className="mt-2 text-3xl font-semibold tracking-tight">{admin.name}</h1>
              <p className="mt-2 text-sm text-slate-300">{admin.email}</p>
            </div>
            <button onClick={handleLogout} className="rounded-full border border-white/20 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-white/10">
              Log Out
            </button>
          </div>
        </section>

        {message ? <div className="rounded-2xl border border-blue-200 bg-blue-50 px-4 py-3 text-sm font-medium text-blue-700">{message}</div> : null}

        <section className="grid gap-6 xl:grid-cols-[1fr,1fr,0.9fr]">
          <form onSubmit={handleHospitalSubmit} className="rounded-[24px] bg-white p-6 shadow-sm">
            <h2 className="text-xl font-semibold text-slate-900">Add Hospital</h2>
            <div className="mt-5 grid gap-3">
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Hospital name" value={hospitalForm.name} onChange={(event) => setHospitalForm((current) => ({ ...current, name: event.target.value }))} required />
              <div className="grid gap-3 md:grid-cols-2">
                <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="City" value={hospitalForm.city} onChange={(event) => setHospitalForm((current) => ({ ...current, city: event.target.value }))} required />
                <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="State" value={hospitalForm.state} onChange={(event) => setHospitalForm((current) => ({ ...current, state: event.target.value }))} required />
              </div>
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Address" value={hospitalForm.address} onChange={(event) => setHospitalForm((current) => ({ ...current, address: event.target.value }))} required />
              <div className="grid gap-3 md:grid-cols-2">
                <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Pincode" value={hospitalForm.pincode} onChange={(event) => setHospitalForm((current) => ({ ...current, pincode: event.target.value }))} />
                <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Phone" value={hospitalForm.phone} onChange={(event) => setHospitalForm((current) => ({ ...current, phone: event.target.value }))} required />
              </div>
              <div className="grid gap-3 md:grid-cols-2">
                <input className="rounded-2xl border border-slate-200 px-4 py-3" type="email" placeholder="Email" value={hospitalForm.email} onChange={(event) => setHospitalForm((current) => ({ ...current, email: event.target.value }))} required />
                <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Website" value={hospitalForm.website} onChange={(event) => setHospitalForm((current) => ({ ...current, website: event.target.value }))} />
              </div>
              <div className="grid gap-3 md:grid-cols-2">
                <input className="rounded-2xl border border-slate-200 px-4 py-3" type="number" step="0.1" min="0" max="5" placeholder="Rating" value={hospitalForm.rating} onChange={(event) => setHospitalForm((current) => ({ ...current, rating: event.target.value }))} required />
                <label className="flex items-center gap-3 rounded-2xl border border-slate-200 px-4 py-3 text-sm text-slate-700">
                  <input type="checkbox" checked={hospitalForm.isOpen24Hours} onChange={(event) => setHospitalForm((current) => ({ ...current, isOpen24Hours: event.target.checked }))} />
                  Open 24 Hours
                </label>
              </div>
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Specialties (comma separated)" value={hospitalForm.specialties} onChange={(event) => setHospitalForm((current) => ({ ...current, specialties: event.target.value }))} required />
            </div>
            <button className="mt-5 rounded-2xl bg-slate-900 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800">Save Hospital</button>
          </form>

          <form onSubmit={handleDoctorSubmit} className="rounded-[24px] bg-white p-6 shadow-sm">
            <h2 className="text-xl font-semibold text-slate-900">Add Doctor</h2>
            <div className="mt-5 grid gap-3">
              <select className="rounded-2xl border border-slate-200 px-4 py-3" value={doctorForm.hospitalId} onChange={(event) => setDoctorForm((current) => ({ ...current, hospitalId: event.target.value }))} required>
                <option value="">Select hospital</option>
                {hospitals.map((hospital) => (
                  <option key={hospital.id} value={hospital.id}>
                    {hospital.name}
                  </option>
                ))}
              </select>
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Doctor name" value={doctorForm.name} onChange={(event) => setDoctorForm((current) => ({ ...current, name: event.target.value }))} required />
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Specialty" value={doctorForm.specialty} onChange={(event) => setDoctorForm((current) => ({ ...current, specialty: event.target.value }))} required />
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Experience (e.g. 12 years)" value={doctorForm.experience} onChange={(event) => setDoctorForm((current) => ({ ...current, experience: event.target.value }))} required />
              <div className="grid gap-3 md:grid-cols-2">
                <input className="rounded-2xl border border-slate-200 px-4 py-3" type="number" min="0" max="5" placeholder="Rating" value={doctorForm.rating} onChange={(event) => setDoctorForm((current) => ({ ...current, rating: event.target.value }))} required />
                <input className="rounded-2xl border border-slate-200 px-4 py-3" type="number" min="0" placeholder="Reviews" value={doctorForm.reviews} onChange={(event) => setDoctorForm((current) => ({ ...current, reviews: event.target.value }))} required />
              </div>
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Qualification" value={doctorForm.qualification} onChange={(event) => setDoctorForm((current) => ({ ...current, qualification: event.target.value }))} required />
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="College" value={doctorForm.college} onChange={(event) => setDoctorForm((current) => ({ ...current, college: event.target.value }))} required />
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Tags (comma separated)" value={doctorForm.tags} onChange={(event) => setDoctorForm((current) => ({ ...current, tags: event.target.value }))} required />
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Availability" value={doctorForm.available} onChange={(event) => setDoctorForm((current) => ({ ...current, available: event.target.value }))} required />
              <input className="rounded-2xl border border-slate-200 px-4 py-3" placeholder="Conditions (comma separated)" value={doctorForm.conditions} onChange={(event) => setDoctorForm((current) => ({ ...current, conditions: event.target.value }))} required />
            </div>
            <button className="mt-5 rounded-2xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white transition hover:bg-blue-700">Save Doctor</button>
          </form>

          <section className="rounded-[24px] bg-white p-6 shadow-sm">
            <h2 className="text-xl font-semibold text-slate-900">Current Hospitals</h2>
            <div className="mt-5 space-y-3">
              {hospitals.length === 0 ? (
                <p className="text-sm text-slate-500">No hospitals added yet.</p>
              ) : (
                hospitals.map((hospital) => (
                  <div key={hospital.id} className="rounded-2xl border border-slate-200 px-4 py-4">
                    <p className="font-semibold text-slate-900">{hospital.name}</p>
                    <p className="mt-1 text-sm text-slate-500">{hospital.city}, {hospital.state}</p>
                    <p className="mt-2 text-sm text-slate-600">{hospital.doctorCount} doctors</p>
                  </div>
                ))
              )}
            </div>
          </section>
        </section>
      </div>
    </main>
  );
}
